--
-- Database: `budgetbrain_db`
--

DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_entry_planner` (IN `p_user_id` INT, IN `p_year` INT, IN `p_month` INT)   BEGIN
	INSERT INTO entries (
		user_id,
        category_id,
        amount,
        description,
        date,
        planned_entry_id,
        completed
	)
    SELECT
		r.user_id,
        r.category_id,
        r.amount,
        r.name,
        DATE(CONCAT(p_year, '-', p_month, '-', r.day_of_month)),
        r.id,
        false
	FROM entry_planner r
    WHERE r.user_id = p_user_id
	AND r.active = true
    
    AND NOT EXISTS (
		SELECT 1 FROM entries e
        WHERE e.planned_entry_id = r.id
        AND YEAR(e.date) = p_year
        AND MONTH(e.date) = p_month
	);
END$$

DELIMITER ;

